import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Creating and editing a page","description":"Create pages, insert blocks, and edit structure and layout.","frontmatter":{"title":"Creating and editing a page","description":"Create pages, insert blocks, and edit structure and layout."},"headers":[],"relativePath":"en/seiten/seite-erstellen.md","filePath":"en/seiten/seite-erstellen.md","lastUpdated":1787319236000}'),s={name:"en/seiten/seite-erstellen.md"};function n(r,e,l,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="creating-and-editing-a-page" tabindex="-1">Creating and editing a page <a class="header-anchor" href="#creating-and-editing-a-page" aria-label="Permalink to &quot;Creating and editing a page&quot;">​</a></h1><h2 id="creating-a-page" tabindex="-1">Creating a page <a class="header-anchor" href="#creating-a-page" aria-label="Permalink to &quot;Creating a page&quot;">​</a></h2><ol><li>Open the <strong>Pages</strong> area in the sidebar.</li><li>Click <strong>Create page</strong>.</li><li>Give it a title.</li></ol><p>The page starts out empty.</p><h2 id="inserting-blocks" tabindex="-1">Inserting blocks <a class="header-anchor" href="#inserting-blocks" aria-label="Permalink to &quot;Inserting blocks&quot;">​</a></h2><p>The editor works like a text document. The placeholder reads:</p><blockquote><p><em>Start typing or press the spacebar to open the block picker</em></p></blockquote><p>Two approaches:</p><ul><li><strong>Just type</strong> — the text becomes a paragraph.</li><li><strong>Press the spacebar</strong> — the block picker opens. Keep typing to filter (<em>Type to filter…</em>), then select the block.</li></ul><p>The picker is split into three groups: <strong>Basic Blocks</strong>, <strong>Special Blocks</strong>, and <strong>Form field Blocks</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Faster than the mouse</p><p>Pressing the spacebar at the start of a line, plus two or three letters, takes you straight to the block you want. &quot;ta&quot; matches the Tab layout, &quot;sum&quot; matches the sum card. For longer pages, that&#39;s noticeably faster than scrolling through the list.</p></div><h2 id="structure-mode" tabindex="-1">Structure mode <a class="header-anchor" href="#structure-mode" aria-label="Permalink to &quot;Structure mode&quot;">​</a></h2><p><strong>Show structure mode</strong> reveals two additional panels:</p><p><strong>Page structure</strong> — the block tree. Here you see the nesting, reorder via drag and drop, and insert precisely where you want:</p><ul><li><strong>Add block</strong> — inside or after a block</li><li><strong>Add tab</strong> — for a Tab layout</li><li><strong>Add step</strong> — for a Stepper layout</li></ul><p><strong>Block settings</strong> — the settings for the selected block. With nothing selected, it shows:</p><blockquote><p><em>Select a block in the structure to see its settings.</em></p></blockquote><p>For blocks without their own settings:</p><blockquote><p><em>There is no settings panel for this block yet.</em></p></blockquote><div class="tip custom-block"><p class="custom-block-title">When structure mode pays off</p><p>For simple text pages, you don&#39;t need it. Once you&#39;re building nested layouts — layout inside layout, tabs with sub-pages — it&#39;s indispensable: in the regular editor it&#39;s hard to tell which block sits inside which.</p></div><h2 id="editing-content-or-layout" tabindex="-1">Editing content or layout <a class="header-anchor" href="#editing-content-or-layout" aria-label="Permalink to &quot;Editing content or layout&quot;">​</a></h2><p>The editor has two editing modes:</p><ul><li><strong>Edit content</strong> — change text and values</li><li><strong>Edit layout</strong> — arrange and nest blocks</li></ul><h2 id="page-settings" tabindex="-1">Page settings <a class="header-anchor" href="#page-settings" aria-label="Permalink to &quot;Page settings&quot;">​</a></h2><p>Via the page menu (<em>Open page menu</em>) you reach the page settings, grouped into sections:</p><h3 id="page" tabindex="-1">Page <a class="header-anchor" href="#page" aria-label="Permalink to &quot;Page&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Set icon &amp; color</strong></td><td>Symbol and color in the navigation</td></tr><tr><td><strong>Add cover image</strong></td><td>Image above the page</td></tr><tr><td><strong>Set background color</strong></td><td>Background of the page</td></tr></tbody></table><h3 id="layout-appearance" tabindex="-1">Layout &amp; appearance <a class="header-anchor" href="#layout-appearance" aria-label="Permalink to &quot;Layout &amp; appearance&quot;">​</a></h3><p><strong>Set page layout</strong> with three options:</p><table tabindex="0"><thead><tr><th>Layout</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Centered page</strong></td><td>Content at a limited width, centered</td></tr><tr><td><strong>Full width</strong></td><td>Content uses the whole window width</td></tr><tr><td><strong>Card view</strong></td><td>Content shown as a raised card</td></tr></tbody></table><p>The note <em>Applies to the Portal display</em> matters: the layout affects the published page, not the editor.</p><p>There&#39;s also <strong>Collapsible navigation</strong> for pages with sub-pages.</p><h3 id="editing-access" tabindex="-1">Editing &amp; access <a class="header-anchor" href="#editing-access" aria-label="Permalink to &quot;Editing &amp; access&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Lock page</strong></td><td><em>Blocks can no longer be edited</em></td></tr><tr><td><strong>Confirm correct account</strong></td><td>Users confirm their identity before continuing</td></tr><tr><td><strong>Auto-submit on load</strong></td><td><em>Submits this page automatically when it loads</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Lock a page against accidental changes</p><p>Once a page is in active use, locking it is worth doing. It prevents someone from accidentally moving a block or overwriting text while viewing it.</p></div><div class="warning custom-block"><p class="custom-block-title">Auto-submit needs complete data</p><p>As with forms: if the page submits itself on load, no one gets the chance to fill in fields. This only makes sense when all values are prefilled via the link — for example to start a Flow via a QR code scan.</p></div><h3 id="usage-in-flows" tabindex="-1">Usage in Flows <a class="header-anchor" href="#usage-in-flows" aria-label="Permalink to &quot;Usage in Flows&quot;">​</a></h3><p>Shows which Flows use this page.</p><div class="tip custom-block"><p class="custom-block-title">Check before deleting</p><p>Before deleting a page, check here. If a Flow step displays it, that Flow will subsequently fail with the error <em>No dedicated interface is assigned to this step</em>.</p></div><h2 id="conditional-visibility" tabindex="-1">Conditional visibility <a class="header-anchor" href="#conditional-visibility" aria-label="Permalink to &quot;Conditional visibility&quot;">​</a></h2><p>Blocks can be shown or hidden depending on entered values. In the <strong>Visibility</strong> section, choose <strong>Field</strong>, <strong>Condition</strong>, and <strong>Value</strong>.</p><p>Available conditions: <em>is empty</em>, <em>is not empty</em>, <em>is true</em>, <em>is false</em>, <em>equals</em>, <em>does not equal</em>, <em>is greater than</em>, <em>is less than</em>.</p><p>The editor shows what applies: <em>Visible when {condition}</em>, plus <em>Currently visible</em> or <em>Currently hidden</em>.</p><p>For more complex cases, there&#39;s <strong>Advanced (ApptiveScript)</strong> with an expression like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>formValues.get(&#39;age&#39;).greaterThan(18)</span></span></code></pre></div><p>→ <a href="/en/referenz/apptivescript-funktionen">ApptiveScript functions</a></p><div class="warning custom-block"><p class="custom-block-title">Top plan only</p><p>Conditional visibility is only available on the Pro plan: <em>Upgrade to Pro to show or hide blocks based on form field values.</em></p></div><p>→ <a href="/en/seiten/sichtbarkeit">Conditional visibility</a></p><h2 id="renaming-and-deleting-a-page" tabindex="-1">Renaming and deleting a page <a class="header-anchor" href="#renaming-and-deleting-a-page" aria-label="Permalink to &quot;Renaming and deleting a page&quot;">​</a></h2><p>Both are done via the page menu. Deletion requires confirmation.</p><div class="danger custom-block"><p class="custom-block-title">Sub-pages disappear too</p><p>Deleting a page also removes its sub-pages. Check the page structure beforehand — and whether a published Portal link points to it.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/seiten/bloecke">Block overview</a></li><li><a href="/en/seiten/layout-bloecke">Layout blocks</a></li><li><a href="/en/seiten/portal-veroeffentlichen">Publishing a Portal</a></li></ul>',53)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
